// ══ VALIDACIÓN DE ENTRADA ══
// Guardrail: lo que entra por un webhook público no se toca sin comprobarlo.
const body = $input.first().json.body || $input.first().json || {};
const err = [];
const m = body.macros_objetivo || {};
const num = (v, k, min, max) => {
  const n = Number(v);
  if (!Number.isFinite(n)) { err.push(`${k}: no es un número`); return 0; }
  if (n < min || n > max) { err.push(`${k}: ${n} fuera de rango [${min}, ${max}]`); return 0; }
  return n;
};
const meta = {
  kcal: m.kcal == null ? null : num(m.kcal, 'kcal', 0, 5000),
  prot: num(m.prot, 'prot', 0, 400),
  carb: num(m.carb, 'carb', 0, 800),
  gras: num(m.gras, 'gras', 0, 300)
};
const sel = Array.isArray(body.seleccion) ? body.seleccion : [];
if (!sel.length) err.push('seleccion: hace falta al menos un módulo');
if (sel.length > 8) err.push(`seleccion: ${sel.length} módulos, el máximo es 8`);
const seleccion = sel.map((s, i) => {
  if (!s || typeof s.id !== 'string' || !/^[A-Z]\d{2}$/.test(s.id)) { err.push(`seleccion[${i}].id inválido`); return null; }
  // El tamaño es OPCIONAL: si viene, se clava; si no, lo resuelve el porcionador.
  let t = s.tamano;
  if (t != null && ![0.5, 1, 1.5, 2, 3, 4].includes(Number(t))) { err.push(`seleccion[${i}].tamano ${t}: debe ser 0.5, 1, 1.5, 2, 3 o 4`); return null; }
  return { id: s.id, tamano: t == null ? null : Number(t) };
}).filter(Boolean);
const ids = seleccion.map(s => s.id);
if (new Set(ids).size !== ids.length) err.push('seleccion: hay ids repetidos');
// Tope de módulos DISTINTOS por categoría (la letra del id): con porciones múltiples
// un segundo módulo cubre cualquier meta y un tercero solo dispara la búsqueda.
const porCat = {};
ids.forEach(i => { porCat[i[0]] = (porCat[i[0]] || 0) + 1; });
const CAT = { P: 'proteína', C: 'carbohidrato', V: 'vegetal', G: 'grasa' };
Object.entries(porCat).forEach(([c, n]) => { if (n > 2) err.push(`seleccion: ${n} módulos de ${CAT[c] || c}; el máximo son 2 por categoría`); });
const sin = ((body.restricciones || {}).sin || []).map(x => String(x).toLowerCase().trim()).filter(Boolean);

return [{ json: {
  ok: err.length === 0,
  errores: err,
  meta, seleccion, sin,
  // id de pedido determinista por contenido + hora, sin Math.random
  pedido_id: 'PED-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + ids.join(''),
  t0: Date.now(),
  recibido: body
}}];

// ══ RESOLUCIÓN DETERMINISTA DEL PLATO ══
// Aquí se produce TODO lo numérico de la respuesta. El agente no escribe ni un
// dígito: solo redacta, y el nodo de verificación comprueba que no se inventó
// ninguna cifra. Es lo que hace el sistema defendible.
const v = $('Validar entrada').first().json;
if (!v.ok) return [{ json: { ...v, abortar: true } }];

// ── el catálogo, tal como vino del Sheets (fuente única de verdad) ──
const filas = $('Leer catálogo').first().json.values || [];
const head = filas[0];
const catalogo = filas.slice(1).filter(r => r && r[0]).map(r => {
  const o = {}; head.forEach((h, i) => { o[h] = r[i]; });
  return {
    id: o.id, nombre: o.nombre, categoria: o.categoria,
    g: Number(o.g_estandar), kcal: Number(o.kcal),
    prot: Number(o.prot), carb: Number(o.carb), gras: Number(o.gras),
    precio_pequena: Number(o.precio_pequena), precio_estandar: Number(o.precio_estandar), precio_grande: Number(o.precio_grande),
    alergenos: String(o.alergenos || '').toLowerCase(),
    alergenos_fuente: o.alergenos_fuente || '',
    tags: String(o.tags || '').toLowerCase(),
    disponible: String(o.disponible || 'si').toLowerCase() === 'si'
  };
});
// ══ MOTOR DETERMINISTA — réplica exacta de js/calc.js de la app ══
// Ni un número de aquí sale de un modelo de lenguaje. Si esto y la app
// discrepan, es un bug que hay que ver, no un redondeo que tolerar.
// Tope de porciones por categoría: réplica de MAX_PORCIONES de data.js. A partir
// de 2 el módulo se repite ("3 porciones" = tres raciones Estándar).
const MAX_PORCIONES = { proteina: 3, carbohidrato: 4, vegetal: 2, grasa: 2 };
const MAX_MODULOS_CAT = 2;
const TODOS = [0.5, 1, 1.5, 2, 3, 4];
function tamanosPermitidos(it) { const tope = MAX_PORCIONES[it.categoria] ?? 1.5; return TODOS.filter(k => k <= tope); }
const ETIQUETA = { 0.5: 'Pequeña', 1: 'Estándar', 1.5: 'Grande', 2: '2 porciones', 3: '3 porciones', 4: '4 porciones' };
const PESO_MACRO = { prot: 2, carb: 1, gras: 1 };
const UMBRAL_G = 4;

// mac(): mismo redondeo que la app. La grasa a 1 decimal, el resto entero.
function mac(it, f) {
  return {
    kcal: Math.round(it.kcal * f),
    prot: Math.round(it.prot * f),
    carb: Math.round(it.carb * f),
    gras: Math.round(it.gras * f * 10) / 10,
    g:    Math.round(it.g * f)
  };
}
// El precio sale del catálogo por tamaño, no de una fórmula: el catálogo es la
// fuente única y sus precios pueden haberse editado a mano.
function precioDe(it, f) {
  // A partir de 2 porciones cada una cuesta lo que la Estándar: misma regla que la app.
  if (f >= 2) return f * it.precio_estandar;
  return f === 0.5 ? it.precio_pequena : f === 1.5 ? it.precio_grande : it.precio_estandar;
}

function porcionar(items, meta, opts) {
  opts = opts || {};
  if (!items || !items.length) return null;
  const den = k => Math.max(meta[k] || 0, 1);
  const wp = PESO_MACRO.prot / den('prot'), wc = PESO_MACRO.carb / den('carb'), wg = PESO_MACRO.gras / den('gras');
  const fijos = opts.fijos || {};
  const opciones = items.map(it => (fijos[it.id] != null ? [fijos[it.id]] : tamanosPermitidos(it)).map(f => {
    const m = mac(it, f);
    return { f, prot: m.prot, carb: m.carb, gras10: Math.round(m.gras * 10), kcal: m.kcal, precio: precioDe(it, f) };
  }));
  const total = opciones.reduce((a, d) => a * d.length, 1);
  // Encuentro en el medio: réplica exacta de js/calc.js. Mismo espacio de búsqueda,
  // mismo óptimo; con ocho módulos 1,7 M de cruces en milisegundos, donde la
  // enumeración plana tumbaba el task runner de n8n (>30 s) con el mismo plato.
  const enumerar = doms => {
    let acc = [{ prot: 0, carb: 0, gras10: 0, kcal: 0, precio: 0, fs: [] }];
    for (const dom of doms) {
      const sig = [];
      for (const a of acc) for (const o of dom)
        sig.push({ prot: a.prot + o.prot, carb: a.carb + o.carb, gras10: a.gras10 + o.gras10,
                   kcal: a.kcal + o.kcal, precio: a.precio + o.precio, fs: a.fs.concat(o.f) });
      acc = sig;
    }
    return acc;
  };
  const corte = Math.ceil(opciones.length / 2);
  const A = enumerar(opciones.slice(0, corte)), B = enumerar(opciones.slice(corte));
  let mejorCoste = Infinity, mejorPrecio = Infinity, ia = -1, ib = -1;
  for (let i = 0; i < A.length; i++) {
    const a = A[i]; const pa = a.prot - meta.prot, ca = a.carb - meta.carb;
    for (let j = 0; j < B.length; j++) {
      const b = B[j];
      const dp = pa + b.prot, dc = ca + b.carb, dg = (a.gras10 + b.gras10) / 10 - meta.gras;
      const coste = wp * (dp < 0 ? -dp : dp) + wc * (dc < 0 ? -dc : dc) + wg * (dg < 0 ? -dg : dg);
      if (coste < mejorCoste - 1e-9 || (coste - mejorCoste < 1e-9 && coste - mejorCoste > -1e-9 && a.precio + b.precio < mejorPrecio)) {
        mejorCoste = coste; mejorPrecio = a.precio + b.precio; ia = i; ib = j;
      }
    }
  }
  const a = A[ia], b = B[ib];
  const factores = a.fs.concat(b.fs);
  const gras = (a.gras10 + b.gras10) / 10;
  const macros = { kcal: a.kcal + b.kcal, prot: a.prot + b.prot, carb: a.carb + b.carb, gras };
  const desviacion = { prot: macros.prot - meta.prot, carb: macros.carb - meta.carb, gras: gras - meta.gras };
  const tamanos = {};
  items.forEach((it, i) => { tamanos[it.id] = factores[i]; });
  return {
    tamanos, macros, desviacion, precio: mejorPrecio, coste: mejorCoste,
    dentroDeUmbral: Math.abs(desviacion.prot) <= UMBRAL_G && Math.abs(desviacion.carb) <= UMBRAL_G && Math.abs(desviacion.gras) <= UMBRAL_G,
    combinacionesEvaluadas: total
  };
}

function proponerCierre(items, meta, candidatos, opts) {
  const base = items && items.length ? porcionar(items, meta, opts) : null;
  if (base && base.dentroDeUmbral) return null;
  if (!candidatos || !candidatos.length) return null;
  const yaEsta = {}; (items || []).forEach(i => { yaEsta[i.id] = true; });
  let mejor = null;
  for (const c of candidatos) {
    if (yaEsta[c.id]) continue;
    const r = porcionar([...(items || []), c], meta, opts);
    if (!mejor || r.coste < mejor.r.coste - 1e-9) mejor = { c, r };
  }
  if (!mejor) return null;
  if (base && mejor.r.coste >= base.coste - 1e-9) return null;
  const tamano = mejor.r.tamanos[mejor.c.id];
  const aporta = mac(mejor.c, tamano);
  let macro = 'carb', ganancia = -Infinity;
  if (base) for (const k of ['prot', 'carb', 'gras']) {
    const g = Math.abs(base.desviacion[k]) - Math.abs(mejor.r.desviacion[k]);
    if (g > ganancia) { ganancia = g; macro = k; }
  }
  return {
    id: mejor.c.id, nombre: mejor.c.nombre, categoria: mejor.c.categoria,
    tamano: ETIQUETA[tamano], g: aporta.g, aporta,
    macro_que_cierra: macro,
    precio_extra: base ? mejor.r.precio - base.precio : mejor.r.precio,
    precio_total_con_propuesta: mejor.r.precio,
    // Tamaños de TODAS las líneas si se acepta: si aceptar reajusta otra línea, el
    // agente lo dice con este dato en vez de inventarse un mecanismo.
    tamanos_resultantes: Object.fromEntries(Object.entries(mejor.r.tamanos).map(([id, f]) => [id, ETIQUETA[f]])),
    // Los totales que quedarían al aceptar, ya calculados: sin esto el modelo
    // los sumaba de cabeza (64 + 48 = 112) y el auditor le tumbaba el texto.
    macros_resultantes: mejor.r.macros,
    desviacion_resultante: mejor.r.desviacion,
    dentro_de_umbral: mejor.r.dentroDeUmbral
  };
}


// ── consultar_menu: lookup determinista con filtros duros ──
function consultarMenu(f) {
  f = f || {};
  return catalogo.filter(it => {
    if (f.categoria && it.categoria !== f.categoria) return false;
    if (f.solo_disponibles !== false && !it.disponible) return false;
    if (f.sin && f.sin.length && f.sin.some(a => it.alergenos.includes(a))) return false;
    if (f.tag && !it.tags.includes(f.tag)) return false;
    return true;
  });
}

const porId = id => catalogo.find(c => c.id === id);
const avisos = [];

// ── los módulos pedidos, con los filtros duros aplicados ──
const items = [], fijos = {}, rechazados = [];
for (const s of v.seleccion) {
  const it = porId(s.id);
  if (!it) { rechazados.push({ id: s.id, motivo: 'no existe en el catálogo' }); continue; }
  if (!it.disponible) { rechazados.push({ id: s.id, nombre: it.nombre, motivo: 'no disponible hoy' }); continue; }
  const choca = v.sin.filter(a => it.alergenos.includes(a));
  if (choca.length) { rechazados.push({ id: s.id, nombre: it.nombre, motivo: `contiene ${choca.join(', ')}` }); continue; }
  // Un tamaño por encima del tope de su categoría no se clava en silencio: se rechaza
  // con su motivo, y el módulo entra libre para que el porcionador lo resuelva.
  if (s.tamano != null && !tamanosPermitidos(it).includes(s.tamano)) {
    rechazados.push({ id: s.id, nombre: it.nombre, motivo: `tamaño ${s.tamano} supera el tope de ${MAX_PORCIONES[it.categoria]} porciones para ${it.categoria}; se resolvió automáticamente` });
    items.push(it);
    continue;
  }
  items.push(it);
  if (s.tamano != null) fijos[it.id] = s.tamano;
}
if (v.sin.length) {
  avisos.push('Los alérgenos del catálogo están derivados del nombre del plato y NO han sido verificados por cocina: no uses esta respuesta como garantía alérgica.');
}

if (!items.length) {
  return [{ json: { ...v, abortar: true, errores: ['ningún módulo de la selección es utilizable'], rechazados, avisos } }];
}

// ── porcionar: recalcula y CONFIRMA lo que la app ya resolvió ──
const r = porcionar(items, v.meta, { fijos });
const ETQ = ETIQUETA;

// ── armar_ticket: aplica los precios del catálogo y totaliza ──
const lineas = items.map(it => {
  const f = r.tamanos[it.id];
  const m = mac(it, f);
  return { id: it.id, nombre: it.nombre, categoria: it.categoria, tamano: ETQ[f], g: m.g,
           macros: { kcal: m.kcal, prot: m.prot, carb: m.carb, gras: m.gras },
           precio: precioDe(it, f) };
});

// ── calculadora: verifica la suma antes de cerrar ──
const suma = lineas.reduce((a, l) => ({
  kcal: a.kcal + l.macros.kcal, prot: a.prot + l.macros.prot,
  carb: a.carb + l.macros.carb, gras: Math.round((a.gras + l.macros.gras) * 10) / 10,
  total: a.total + l.precio
}), { kcal: 0, prot: 0, carb: 0, gras: 0, total: 0 });

const cuadra = suma.kcal === r.macros.kcal && suma.prot === r.macros.prot
            && suma.carb === r.macros.carb && Math.abs(suma.gras - r.macros.gras) < 1e-9
            && suma.total === r.precio;
if (!cuadra) avisos.push('DISCREPANCIA: la suma de las líneas no cuadra con el porcionado. Gana la suma de las líneas.');

// ── propuesta de cierre: el error, el valor percibido y el upsell, a la vez ──
let propuesta = null;
if (!r.dentroDeUmbral) {
  const porCat = {};
  items.forEach(i => { porCat[i.categoria] = (porCat[i.categoria] || 0) + 1; });
  const candidatos = consultarMenu({ sin: v.sin })
    .filter(c => !items.some(i => i.id === c.id))
    .filter(c => (porCat[c.categoria] || 0) < MAX_MODULOS_CAT);
  propuesta = proponerCierre(items, v.meta, candidatos, { fijos });
}

const numeros = {};
lineas.forEach(l => { numeros[l.id] = { g: l.g, precio: l.precio, ...l.macros }; });

return [{ json: {
  ...v, abortar: false, rechazados, avisos,
  lineas,
  macros_totales: { kcal: suma.kcal, prot: suma.prot, carb: suma.carb, gras: suma.gras },
  desviacion: r.desviacion,
  dentro_de_umbral: r.dentroDeUmbral,
  total: suma.total,
  propuesta_cierre: propuesta,
  combinaciones_evaluadas: r.combinacionesEvaluadas,
  suma_cuadra: cuadra,
  catalogo_filas: catalogo.length,
  // universo de cifras legítimas: la verificación comprobará contra esto
  numeros_permitidos: numeros
}}];

// consultar_menu — lookup DETERMINISTA sobre el catálogo del día.
// No es RAG: los macros y los precios son tabla exacta, no texto parecido.
const d = $('Resolver plato').first().json;
let f = {};
try { f = typeof query === 'string' ? JSON.parse(query) : (query || {}); } catch (e) { f = {}; }
const filas = $('Leer catálogo').first().json.values || [];
const head = filas[0];
const cat = filas.slice(1).filter(r => r && r[0]).map(r => { const o = {}; head.forEach((h, i) => { o[h] = r[i]; }); return o; });
const sin = (f.sin || d.sin || []).map(x => String(x).toLowerCase());
const out = cat.filter(it => {
  if (f.categoria && it.categoria !== f.categoria) return false;
  if (String(it.disponible).toLowerCase() !== 'si') return false;
  if (sin.length && sin.some(a => String(it.alergenos).toLowerCase().includes(a))) return false;
  if (f.tag && !String(it.tags).toLowerCase().includes(String(f.tag).toLowerCase())) return false;
  if (f.id && it.id !== f.id) return false;
  return true;
});
return JSON.stringify({ encontrados: out.length, modulos: out,
  aviso_alergenos: 'alergenos derivados del nombre del plato, SIN verificar por cocina' });

// porcionar — recalcula y CONFIRMA lo que la app ya resolvió. Si discrepan,
// gana n8n y la discrepancia queda registrada. La doble capa es deliberada:
// permite demostrar que el número es correcto, no solo que suena razonable.
const d = $('Resolver plato').first().json;
return JSON.stringify({
  tamanos: d.lineas.map(l => ({ id: l.id, nombre: l.nombre, tamano: l.tamano, g: l.g, precio: l.precio, macros: l.macros })),
  macros_totales: d.macros_totales,
  desviacion: d.desviacion,
  dentro_de_umbral: d.dentro_de_umbral,
  combinaciones_evaluadas: d.combinaciones_evaluadas,
  nota: 'optimo global por busqueda exhaustiva sobre el producto de los dominios de cada modulo (hasta 4 porciones segun categoria), proteina a peso doble; combinaciones_evaluadas dice cuantas se recorrieron'
});

// calculadora — verifica la suma antes de cerrar. Suma las líneas de nuevo,
// desde cero, y compara contra el total que se va a responder.
const d = $('Resolver plato').first().json;
const s = d.lineas.reduce((a, l) => ({
  kcal: a.kcal + l.macros.kcal, prot: a.prot + l.macros.prot,
  carb: a.carb + l.macros.carb, gras: Math.round((a.gras + l.macros.gras) * 10) / 10,
  total: a.total + l.precio
}), { kcal: 0, prot: 0, carb: 0, gras: 0, total: 0 });
return JSON.stringify({
  suma_de_lineas: s,
  totales_declarados: { ...d.macros_totales, total: d.total },
  cuadra: s.kcal === d.macros_totales.kcal && s.prot === d.macros_totales.prot
       && s.carb === d.macros_totales.carb && Math.abs(s.gras - d.macros_totales.gras) < 1e-9
       && s.total === d.total,
  contra_la_meta: { objetivo: d.meta, desviacion: d.desviacion, umbral_g: 4 }
});

// armar_ticket — aplica los precios del catálogo y totaliza. Los precios NO se
// calculan aquí: se leen del catálogo, que es la fuente única.
const d = $('Resolver plato').first().json;
return JSON.stringify({
  pedido_id: d.pedido_id,
  lineas: d.lineas.map(l => ({ id: l.id, nombre: l.nombre, tamano: l.tamano, g: l.g, precio_mxn: l.precio })),
  total_mxn: d.total,
  propuesta_cierre: d.propuesta_cierre
    ? { nombre: d.propuesta_cierre.nombre, tamano: d.propuesta_cierre.tamano,
        g: d.propuesta_cierre.g, precio_extra_mxn: d.propuesta_cierre.precio_extra,
        macro_que_cierra: d.propuesta_cierre.macro_que_cierra }
    : null
});

// ══ VERIFICACIÓN — el guardrail que hace defendible el sistema ══
// La respuesta se ENSAMBLA aquí, con los números del nodo determinista. Del
// agente se toma únicamente texto. Y ese texto se audita: cualquier cifra que
// no salga del cálculo se marca como inventada y la explicación se sustituye
// por una redactada en código. Así "ningún número viene del modelo" no es una
// promesa: es una comprobación que se ejecuta en cada petición.
const d = $('Resolver plato').first().json;
const salidaAgente = $input.first().json;
const bruto = String(salidaAgente.output ?? salidaAgente.text ?? '').trim();

// Conjunto de cifras legítimas: todo lo que produjo el cálculo.
const permitidos = new Set();
// Los flotantes binarios (1.3000000000000007) hacían que el auditor marcase
// como inventado un 1.3 que era exactamente el número calculado. Se admite el
// valor con sus redondeos razonables, en positivo y en valor absoluto.
const add = n => {
  if (n == null || !Number.isFinite(Number(n))) return;
  const x = Number(n);
  for (const v of [x, Math.abs(x)]) {
    permitidos.add(String(v));
    permitidos.add(String(Math.round(v)));
    permitidos.add(String(Math.round(v * 10) / 10));
    permitidos.add(String(Math.round(v * 100) / 100));
  }
};
[d.meta.kcal, d.meta.prot, d.meta.carb, d.meta.gras, d.total,
 d.macros_totales.kcal, d.macros_totales.prot, d.macros_totales.carb, d.macros_totales.gras,
 d.desviacion.prot, d.desviacion.carb, d.desviacion.gras].forEach(add);
// El número de porciones de cada línea ("3 porciones") también es una cifra que
// el modelo puede citar con razón: sale de las herramientas tal cual.
const K_DE = { 'Pequeña': 0.5, 'Estándar': 1, 'Grande': 1.5, '2 porciones': 2, '3 porciones': 3, '4 porciones': 4 };
(d.lineas || []).forEach(l => { add(l.g); add(l.precio); Object.values(l.macros).forEach(add); if (K_DE[l.tamano] >= 2) add(K_DE[l.tamano]); });
add(d.lineas ? d.lineas.length : null);
// combinaciones_evaluadas también viaja al agente: es un número del cálculo, no inventado.
add(d.combinaciones_evaluadas);
if (d.propuesta_cierre) {
  const p = d.propuesta_cierre;
  add(p.g); add(p.precio_extra); add(p.precio_total_con_propuesta);
  if (K_DE[p.tamano] >= 2) add(K_DE[p.tamano]);
  Object.values(p.tamanos_resultantes || {}).forEach(t => { if (K_DE[t] >= 2) add(K_DE[t]); });
  Object.values(p.aporta || {}).forEach(add);
  Object.values(p.macros_resultantes || {}).forEach(add);
  Object.values(p.desviacion_resultante || {}).forEach(add);
}

const citados = (bruto.match(/\d+(?:[.,]\d+)?/g) || []).map(s => s.replace(',', '.'));
const inventados = citados.filter(n => !permitidos.has(n) && !permitidos.has(String(Number(n))));

// Explicación de respaldo, escrita en código a partir de los mismos números.
function explicarEnCodigo() {
  const p = [];
  p.push(`Tu plato queda en ${d.macros_totales.kcal} kcal con ${d.macros_totales.prot} g de proteína, ${d.macros_totales.carb} g de carbohidratos y ${d.macros_totales.gras} g de grasas.`);
  const fuera = ['prot', 'carb', 'gras'].filter(k => Math.abs(d.desviacion[k]) > 4);
  const LBL = { prot: 'proteína', carb: 'carbohidratos', gras: 'grasas' };
  if (!fuera.length) p.push('Los tres macros caen dentro de tu meta.');
  else p.push('Fuera de meta: ' + fuera.map(k => `${LBL[k]} ${d.desviacion[k] > 0 ? '+' : ''}${d.desviacion[k]} g`).join(', ') + '.');
  if (d.propuesta_cierre) {
    const c = d.propuesta_cierre;
    p.push(`Para cerrarlo puedes añadir ${c.nombre} en tamaño ${c.tamano} (${c.g} g): aporta ${c.aporta[c.macro_que_cierra]} g de ${LBL[c.macro_que_cierra]} por ${c.precio_extra} MXN más.`);
  }
  return p.join(' ');
}

const limpio = bruto.length > 0 && inventados.length === 0;
const explicacion = limpio ? bruto : explicarEnCodigo();

const respuesta = {
  pedido_id: d.pedido_id,
  lineas: d.lineas,
  macros_totales: d.macros_totales,
  desviacion: d.desviacion,
  dentro_de_umbral: d.dentro_de_umbral,
  // La app manda tamaños en `seleccion`. Si los mandó todos y coinciden con lo
  // que resuelve n8n, se declara la coincidencia; si no, gana n8n y se registra.
  coincide_con_la_app: (() => {
    const pedidos = d.seleccion.filter(s => s.tamano != null);
    if (!pedidos.length) return null;
    const ETQ = { 0.5: 'Pequeña', 1: 'Estándar', 1.5: 'Grande', 2: '2 porciones', 3: '3 porciones', 4: '4 porciones' };
    return pedidos.every(s => {
      const l = d.lineas.find(x => x.id === s.id);
      return l && l.tamano === ETQ[s.tamano];
    });
  })(),
  propuesta_cierre: d.propuesta_cierre,
  total: d.total,
  explicacion,
  avisos: d.avisos,
  rechazados: d.rechazados,
  auditoria: {
    numeros_citados_por_el_modelo: citados.length,
    numeros_inventados: inventados,
    explicacion_del_modelo_aceptada: limpio,
    suma_cuadra: d.suma_cuadra,
    combinaciones_evaluadas: d.combinaciones_evaluadas,
    catalogo_filas: d.catalogo_filas,
    ms: Date.now() - d.t0
  }
};
return [{ json: respuesta }];
